//! Cargo-driven `d3dwine.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is d3dwine-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x76060000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff4d000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff4d000000u64)),
        o => panic!("d3dwine-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:wine", "engine:c:vkd3d", "engine:c:dxguid", "engine:oldnames", "import:opengl32", "import:user32", "import:gdi32_vista", "import:gdi32", "import:advapi32", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll"],
        "x86_64" => &["body", "engine:wine", "engine:c:vkd3d", "engine:c:dxguid", "engine:oldnames", "import:opengl32", "import:user32", "import:gdi32_vista", "import:gdi32", "import:advapi32", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll"],
        "aarch64" => &["body", "engine:wine", "engine:c:vkd3d", "engine:c:dxguid", "engine:oldnames", "import:opengl32", "import:user32", "import:gdi32_vista", "import:gdi32", "import:advapi32", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/directx/wine/wined3d",
        "dll/directx/wine/wined3d",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "vendor/vkd3d/include",
        "vendor/vkd3d/include/private",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINE_NO_NAMELESS_EXTENSION",
        "WINVER=0x0600",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_USE_MATH_DEFINES",
        "_WIN32_WINNT=0x0600",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    // cmake built the body with these RUSTFLAGS (its rust_staticlib_variant ENV).
    let body_rustflags = match arch.as_str() {
        "x86" => Some("-C target-feature=+sse,+sse2"),
        _ => None,
    };
    let mut link = Linker::new(target_json);
    if let Some(flags) = body_rustflags {
        link = link.rust_build_rustflags(flags);
    }
    link
        .rust_staticlib("d3dwine-rust")
        .c_from_compile_db("d3dwine_shims", &["dll/directx/wine/wined3d/rust_cohab_stub.c", "dll/directx/wine/wined3d/rust_varargs_shim.c"])
        .rc("dll/directx/wine/wined3d/resource.rc", rc_includes, rc_flags, rc_defines)
        .rc("dll/directx/wine/wined3d/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/directx/wine/wined3d/wined3d.spec", "d3dwine.dll")
        .import_lib("dll/opengl/opengl32/opengl32.spec", "opengl32.dll", "opengl32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32_vista/gdi32_vista.spec", "gdi32_vista.dll", "gdi32_vista")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
